import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1171, own='cte_94.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 747 Correctional Services ----
H("747.d.1.A",3,"A student studies how county jails, state prisons and federal penitentiaries each developed over time. This is examining:","the history of corrections at several levels",["only cooking history","only sports history","only weather history"],"Corrections history spans municipal to federal levels.")
H("747.d.1.A",4,"Which statement fits the history of corrections in the United States?","Facilities and reform ideas changed as laws and public views changed",["Corrections never changed","Only one prison has ever existed","Prisons began in space"],"The system evolved over time.")
H("747.d.1.B",3,"A new jailer reads the employee handbook to learn the code of conduct and what happens after a violation. This is studying:","rules of conduct and disciplinary guidelines",["recipes","sports scores","bus routes"],"Employees must know conduct rules.")
H("747.d.1.B",4,"Why must correctional employees follow written conduct rules?","They keep staff accountable and the facility safe and lawful",["They are decorations","They apply only to inmates","They are optional"],"Rules protect staff, inmates and the public.")
H("747.d.1.C",3,"A student considers whether she can handle shift work, close contact with inmates and strict rules before choosing a corrections career. This is:","analyzing personal responsibilities and preferences against job requirements",["ignoring the job","choosing at random","avoiding all careers"],"Self-assessment matches people to careers.")
H("747.d.1.C",4,"Which question best helps a person decide if corrections fits them?","Am I comfortable with structure, shift work and enforcing rules?",["What color is the building?","Is the parking lot big?","Do the guards like pizza?"],"Fit depends on job demands.")
H("747.d.1.D",3,"A graduate looks at county, state and federal job boards and calls a sheriff's office about openings. This is:","searching effectively for employment in corrections",["avoiding work","quitting school","ignoring openings"],"Job search uses multiple sources.")
H("747.d.1.D",4,"Which source is most useful for finding open correctional officer positions in a county?","The county's official employment page",["A random social post","A rumor","A TV ad for snacks"],"Official pages list real openings.")
H("747.d.2.A",3,"An employer lists clear speaking, punctuality and honesty as top expectations for jailers. These are:","employer expectations in corrections",["student privileges","vacation plans","school lunches"],"Employers expect these traits.")
H("747.d.2.A",4,"Arriving on time, following orders and communicating clearly all show that an employee meets:","employer expectations",["no expectations","only personal goals","only student goals"],"They are common workplace expectations.")
H("747.d.2.B",3,"A state prison requires its officers to meet standards for training, fitness and ethics. These are:","professional standards in correctional work",["gym rules for visitors","school dress codes","menu choices"],"Standards set the level of professional work.")
H("747.d.2.B",4,"Professional standards in corrections help ensure that officers:","perform duties competently and ethically",["avoid all training","ignore laws","choose rules at will"],"Standards maintain quality.")
H("747.d.2.C",3,"A correctional officer refuses a bribe from an inmate's family to smuggle in a phone. This protects:","the ethical responsibility to safeguard people and the facility",["only the officer's pay","nothing","only the family"],"Contraband puts everyone at risk.")
H("747.d.2.C",4,"An officer's ethical duty to protect inmates' safety includes:","preventing harm and reporting abuse",["ignoring abuse","joining in","hiding reports"],"Officers must protect those in custody.")
H("747.d.3.A",3,"A trainee learns what 'classification', 'contraband' and 'segregation' mean in jail work. This is defining:","technical concepts and vocabulary of corrections",["cooking terms","sports terms","music terms"],"Vocabulary supports clear communication.")
H("747.d.3.A",4,"Which term describes illegal or prohibited items in a secure facility?","contraband",["curriculum","ballot","receipt"],"Contraband is banned material.")
H("747.d.3.B",3,"During a staff meeting about a lockdown drill, a trainee nods, takes notes and adds a suggestion when asked. This shows:","active listening and contributing to group discussion",["ignoring the group","interrupting","sleeping"],"Participation includes listening and contributing.")
H("747.d.3.B",4,"Which behavior best shows active listening in a shift briefing?","Taking notes and asking relevant questions",["Looking at a phone","Talking over others","Leaving early"],"Active listeners engage.")
H("747.d.4.A",3,"A supervisor gives instructions over the radio and the officer repeats them back to confirm. This is applying:","listening skills to obtain and clarify information",["ignoring orders","guessing","interrupting"],"Repeating back confirms understanding.")
H("747.d.4.A",4,"An officer is unsure what a supervisor meant by 'secure the block.' The best action is to:","ask a clarifying question",["guess","do nothing","leave the post"],"Clarify to avoid mistakes.")
H("747.d.4.B",3,"A veteran officer explains to a rookie what 'count', 'sally port' and 'tier' mean. This is:","explaining technical vocabulary in plain terms",["hiding information","using slang only","avoiding communication"],"Clear explanation helps new staff.")
H("747.d.4.B",4,"When explaining a facility term to a new volunteer, the best approach is to:","use simple words and examples",["use more jargon","say nothing","walk away"],"Plain language aids understanding.")
H("747.d.5.A",3,"A jailer finds an inmate unresponsive and begins CPR while calling for help and an AED. This is applying:","first aid, CPR and AED procedures",["avoiding the incident","only paperwork","ignoring the emergency"],"Emergency care saves lives.")
H("747.d.5.A",4,"What should an officer do first when finding an unresponsive person?","Check the scene for safety and call for help",["Leave","Move the person at once","Wait quietly"],"Safety and help come first.")
H("747.d.5.B",3,"An officer wears gloves before touching an inmate's bleeding cut. This follows:","standard precautions for infection control",["ignoring safety","spreading germs","an outdated rule"],"Gloves block exposure to blood.")
H("747.d.5.B",4,"Standard precautions treat all blood and body fluids as:","potentially infectious",["always safe","valueless","food"],"Everyone follows the same protection.")
H("747.d.5.C",3,"A kitchen worker in a jail must follow Safety Data Sheet instructions for a cleaning chemical. This is:","using special requirements for hazardous materials to stay safe",["ignoring labels","mixing chemicals","skipping gloves"],"SDS guide safe handling.")
H("747.d.5.C",4,"Which practice is correct when handling a hazardous cleaning product at a facility?","Read the label and wear the recommended protective gear",["Mix it with other cleaners","Skip gloves","Store it unlabeled"],"Follow safety directions.")
H("747.d.6.A",3,"An officer needs lawful grounds before taking a person into custody. This shows applying:","constitutional laws, including laws of arrest",["personal opinion","guesswork","random rules"],"Arrests must meet legal rules.")
H("747.d.6.A",4,"Why must corrections staff know constitutional law?","Their actions must respect inmates' and citizens' legal rights",["It makes shifts shorter","It is only for judges","It has no use"],"Rights limit what officers may do.")
H("747.d.6.B",3,"A court ruling changes how facilities must provide medical care to inmates. This is an example of:","the impact of the U.S. legal system on corrections",["no connection","a weather effect","a cooking rule"],"Courts shape correctional practice.")
H("747.d.6.B",4,"Court decisions can influence corrections by:","setting standards for conditions and treatment",["ending all prisons","removing all rules","deleting policies"],"Rulings set legal requirements.")
H("747.d.6.C",3,"A person sues a neighbor over a fence, while another is charged by the state for burglary. These examples show the difference between:","the civil and criminal justice systems",["two weather systems","two sports leagues","two school districts"],"Civil is private disputes; criminal is offenses against the state.")
H("747.d.6.C",4,"A key difference between civil and criminal cases is that criminal cases:","are brought by the government and can result in jail or prison",["are always private","never use evidence","never reach court"],"The state prosecutes crimes.")
H("747.d.6.D",3,"An officer calmly separates two arguing inmates and speaks quietly to lower tension. This is using:","techniques to manage a crisis and protect rights",["escalation","ignoring the problem","shouting"],"De-escalation protects everyone.")
H("747.d.6.D",4,"Which action is an appropriate first step in managing an inmate crisis?","Stay calm, assess the situation and use verbal de-escalation",["Use force immediately","Walk away","Argue loudly"],"Calm assessment comes first.")
H("747.d.6.E",3,"An officer must follow state law and procedure when conducting a search after an arrest. This shows:","executing arrest, search and seizure protocols lawfully",["ignoring statutes","searching at random","skipping steps"],"Legal procedure protects evidence and rights.")
H("747.d.6.E",4,"Evidence obtained from an unlawful search may be:","excluded from court",["always accepted","worth extra points","automatically sealed"],"The exclusionary rule applies.")
H("747.d.6.F",3,"Before questioning a suspect in custody, an officer reads the Miranda warning. This reflects the:","Fifth Amendment protection against self-incrimination",["right to free food","right to vote","right to travel"],"Miranda rights stem from the Fifth Amendment.")
H("747.d.6.F",4,"The Fifth Amendment gives a person in custody the right to:","remain silent and not incriminate themselves",["avoid all questions forever","choose the judge","skip the trial"],"Silence is protected.")
H("747.d.6.G",3,"A defendant is tried by a jury of citizens and has a fair hearing under the law. This reflects:","trial, jury and due process rights",["no rights","lost rights","no process"],"These are core legal rights.")
H("747.d.6.G",4,"Due process means that the government must:","follow fair procedures before taking life, liberty or property",["act however it wants","skip hearings","ignore laws"],"Fair procedure is required.")
H("747.d.6.H",3,"Citizens and non-citizens alike must be treated lawfully when detained, but in some cases federal law governs how non-citizens are held. This asks when:","citizens and non-citizens may be lawfully detained",["no one can be detained","only tourists can be","only adults pay fines"],"Detention rules are set by law.")
H("747.d.6.H",4,"Which principle applies to anyone held in custody in the United States?","They must be held lawfully and treated according to the law",["No rules apply","Only citizens have protection","They may be held forever without review"],"Legal protections apply broadly.")
H("747.d.7.A",3,"An inmate shows signs of a serious mental disorder and an officer follows facility procedures to request mental health staff. This is:","applying appropriate procedures for individuals with mental disorders",["ignoring the inmate","punishing symptoms","laughing"],"Mental health needs special handling.")
H("747.d.7.A",4,"When an inmate appears disoriented and talks to unseen people, officers should:","notify supervisors and mental health staff",["ignore it","make fun","use force at once"],"Refer to qualified staff.")
H("747.d.7.B",3,"An officer arranges for an inmate who uses a wheelchair to reach the dining hall safely. This is:","executing protocols to assist people with disabilities",["denying access","ignoring needs","blocking entry"],"Accessibility is required.")
H("747.d.7.B",4,"Which action best assists an inmate who is hard of hearing during a briefing?","Face the person, speak clearly and provide written instructions",["Shout from behind","Ignore the need","Use only jargon"],"Provide an effective accommodation.")
H("747.d.7.C",3,"The Americans with Disabilities Act requires jails to provide equal access to programs. This is its impact on:","inmates and correctional facilities",["only schools","only stadiums","only airports"],"ADA applies to correctional programs.")
H("747.d.7.C",4,"The ADA prohibits correctional facilities from:","discriminating against people with disabilities in programs and services",["housing inmates","using locks","giving meals"],"Discrimination is illegal.")
H("747.d.8.A",3,"A counselor explains that conflicts often start when basic needs like respect or safety are threatened. This is examining:","the origins of conflict and the needs behind behavior",["ignoring people","unrelated hobbies","sports rules"],"Needs drive behavior.")
H("747.d.8.A",4,"Which need most often triggers conflict in a crowded dayroom?","a need for respect or personal space",["weather reports","video games","pizza topping choice"],"Needs for respect and space trigger tension.")
H("747.d.8.B",3,"One officer answers an insult with a threat and the argument gets louder. Another answers calmly and it fades. This is analyzing:","different responses to conflict and their results",["no responses","random luck","only weather"],"Responses shape outcomes.")
H("747.d.8.B",4,"Which response to conflict is most likely to lower tension?","Listening and responding calmly",["Escalating insults","Ignoring safety","Threatening"],"Calm responses calm others.")
H("747.d.8.C",3,"Two staff members each state their concerns, separate the problem from the person and agree on a solution. This is:","principle-centered conflict resolution",["avoiding conflict","winning at all costs","blaming"],"Focus on interests and solutions.")
H("747.d.8.C",4,"A key step in principle-centered conflict resolution is to:","focus on interests and shared goals",["win by force","ignore the other side","assign blame first"],"Solutions come from interests.")
H("747.d.8.D",3,"An officer notices an inmate's clenched fists, raised voice and fast pacing and decides the person is angry. This is:","interpreting visual and vocal cues",["ignoring signs","random guessing","only paperwork"],"Body language and tone carry meaning.")
H("747.d.8.D",4,"Rapid pacing, loud speech and tense posture most likely indicate:","agitation or anger",["calm","sleepiness","hunger only"],"These cues show agitation.")
H("747.d.9.A",3,"A new officer reviews what to do at the control room, the main gate and a housing unit. This is:","reviewing security post procedures",["learning to cook","playing games","avoiding duty"],"Each post has written procedures.")
H("747.d.9.A",4,"Why do security posts have written procedures?","So every officer performs duties the same safe way",["To fill space","To confuse staff","They don't matter"],"Procedures keep operations consistent.")
H("747.d.9.B",3,"Fences, cameras and a patrol road around a prison make up its:","perimeter security system",["school grounds","parking lot","visitor center"],"Perimeters prevent escape and intrusion.")
H("747.d.9.B",4,"A perimeter security system is important because it helps:","prevent escapes and keep unauthorized people out",["bring in contraband","hide visitors","reduce staffing"],"It controls entry and exit.")
H("747.d.9.C",3,"An officer chooses to use only the minimum force needed to stop a physical threat. This is:","appraising the situation and selecting appropriate force",["excessive force","ignoring danger","random action"],"Force must be proportional.")
H("747.d.9.C",4,"The principle that force must match the level of threat is called:","the use of reasonable and proportional force",["unlimited force","no force ever","force by rank"],"Force should be necessary and reasonable.")
H("747.d.9.D",3,"A facility drills evacuation, lockdown and staff roles before an emergency occurs. This is:","pre-event planning to respond to crises",["post-event cleanup","ignoring risk","random action"],"Planning ahead improves response.")
H("747.d.9.D",4,"Pre-event planning for a crisis includes:","assigning roles, practicing drills and stocking supplies",["waiting until it happens","avoiding drills","hiding plans"],"Preparation improves response.")
H("747.d.9.E",3,"During a disturbance, an officer follows crisis protocols to protect staff and inmates and respect their rights. This is:","performing crisis management to protect individual and societal rights",["using unlimited force","ignoring the event","leaving"],"Crisis management balances safety and rights.")
H("747.d.9.E",4,"Effective crisis management in a facility aims to:","restore order while protecting safety and rights",["increase conflict","hide the event","punish everyone"],"The goal is safe resolution.")
H("747.d.10.A",3,"An officer follows written rules for supervising inmates and handing out discipline fairly. This shows knowledge of:","policies and procedures for supervision and discipline",["no rules","personal opinion","random choices"],"Consistent procedures keep order.")
H("747.d.10.A",4,"Why must inmate discipline follow written policy?","It ensures fairness and legal compliance",["It speeds paperwork","It looks nice","It saves ink"],"Policy prevents abuse.")
H("747.d.10.B",3,"An officer uses an approved technique to place restraints on a resisting person while avoiding injury. This is:","protocol designed to restrain individuals without harm",["unlawful force","guesswork","ignoring training"],"Approved methods limit injury.")
H("747.d.10.B",4,"Proper restraint protocol aims to:","control a person safely with minimal risk of injury",["cause pain","delay response","skip documentation"],"Safety for all is the aim.")
H("747.d.10.C",3,"A facility plans how staff will respond to fires, storms and hostage situations. This is developing:","emergency plans and procedures for correctional facilities",["recipes","sports lineups","class schedules"],"Plans cover many emergencies.")
H("747.d.10.C",4,"A facility emergency plan should be:","written, practiced and updated regularly",["secret from staff","never practiced","rarely read"],"Plans are only useful if known and current.")
H("747.d.10.D",3,"Kitchen staff in a jail must follow safe food-handling rules to prevent illness. This describes:","the process and critical elements of food services",["no rules","only weather","only sports"],"Food service needs safety and controls.")
H("747.d.10.D",4,"A critical element of food services in a facility is:","safe preparation and controlled distribution",["random cooking","serving unlabeled food","ignoring allergies"],"Safety and control matter.")
H("747.d.10.E",3,"A new inmate arrives, is searched, photographed, classified and given an orientation. This is the:","steps for processing inmates",["parole process","court trial","release process"],"Intake includes reception, orientation and classification.")
H("747.d.10.E",4,"Classification of a new inmate determines:","housing, security level and program needs",["only uniform color","only cell color","visiting hours only"],"Classification guides placement.")
H("747.d.10.F",3,"A student role-plays a parole board interviewer asking an inmate about plans after release. This is:","conducting a simulated parole interview",["a sentencing hearing","a trial","an arrest"],"Parole interviews assess readiness for release.")
H("747.d.10.F",4,"During a parole interview, an inmate's plan should show:","housing, work and support after release",["no plans","only complaints","only excuses"],"Boards want a realistic plan.")
H("747.d.10.G",3,"A program that provides job training and counseling to people leaving prison is a:","prisoner re-entry program",["school fair","sports camp","recipe class"],"Re-entry programs help people return to society.")
H("747.d.10.G",4,"Re-entry programs aim to reduce:","the chance that people reoffend",["employment","education","housing"],"They support successful return.")
H("747.d.10.H",3,"A facility holds an open house and tells residents how it keeps the neighborhood safe. This shows the importance of:","public relations with communities and citizens",["secrecy","conflict","isolation"],"Good relations build trust.")
H("747.d.10.H",4,"Public relations matters to a correctional agency because it:","builds community trust and understanding",["hides problems","avoids questions","ends oversight"],"Communication builds trust.")
H("747.d.11.A",3,"Direct supervision, indirect supervision and intermittent supervision describe the three main:","models of detention facilities",["school schedules","court levels","police ranks"],"Detention facilities use these supervision models.")
H("747.d.11.A",4,"In a direct supervision facility, officers:","stay inside the housing unit with the inmates",["watch only by camera","stay outside the building","never interact"],"Direct supervision places staff among inmates.")
H("747.d.11.B",3,"A detention officer's core duties include maintaining security, supervising inmates and:","keeping accurate records of activity",["setting court dates","writing laws","choosing judges"],"Officers document events.")
H("747.d.11.B",4,"Which duty is central to a detention officer's role?","Ensuring the safety and security of the facility",["Setting bail amounts","Prosecuting cases","Passing laws"],"Safety and security come first.")
H("747.d.11.C",3,"An inmate claims they were denied needed medical care. This raises an issue of:","prisoners' constitutional rights",["menu preferences","TV channels","clothing colors"],"Medical care is a constitutional issue.")
H("747.d.11.C",4,"Which issue involves prisoners' constitutional rights?","protection from cruel and unusual punishment",["choosing a cell color","selecting a meal brand","picking visiting day"],"The Eighth Amendment applies.")
H("747.d.12.A",3,"An officer is offered a favor by an inmate for looking away from a rule. Rejecting it shows the importance of:","ethical judgment and behavior in criminal justice",["personal gain","carelessness","dishonesty"],"Ethics guide professional behavior.")
H("747.d.12.A",4,"Ethical behavior in criminal justice work means:","acting honestly and fairly even when no one is watching",["bending rules","favoring friends","hiding errors"],"Integrity is consistent.")
H("747.d.12.B",3,"Officers must keep professional boundaries and avoid personal relationships with inmates. This is a human-relations issue between:","staff and prisoners",["court and press","fire and EMS","teachers and parents"],"Boundaries protect safety and fairness.")
H("747.d.12.B",4,"Which is a human-relations issue between staff and prisoners?","maintaining fairness and professional boundaries",["buying lunch","choosing uniforms","building signs"],"Fair treatment avoids favoritism.")
H("747.d.12.C",3,"Both inmates and officers face stress, but officers may deal with long shifts and danger while inmates deal with confinement. This is:","comparing stress and stress-related issues for correctional staff and inmates",["ignoring stress","only a vacation","only a hobby"],"Stress affects both groups differently.")
H("747.d.12.C",4,"A healthy way for correctional personnel to cope with stress is to:","use exercise, rest and support programs",["skip sleep","avoid help","ignore symptoms"],"Healthy coping lowers stress.")
H("747.d.12.D",3,"A county jail holds training so staff understand the customs and needs of the diverse people they supervise. This is:","promoting cultural awareness in corrections",["ignoring differences","creating conflict","avoiding training"],"Awareness improves respect and safety.")
H("747.d.12.D",4,"Cultural awareness training helps officers:","communicate respectfully and avoid misunderstandings",["avoid all training","show bias","ignore needs"],"Understanding reduces conflict.")
H("747.d.12.E",3,"Laws that protect employees and inmates from discrimination and harassment are:","state and federal civil rights laws",["traffic laws only","tax laws only","school rules only"],"Civil rights laws cover harassment and discrimination.")
H("747.d.12.E",4,"Sexual harassment of a coworker or inmate by staff is:","prohibited by law and agency policy",["permitted","a joke","a privilege"],"It violates civil rights law.")
H("747.d.13.A",3,"During intake, a nurse asks questions to see whether a new inmate is at risk of self-harm. This is a method of:","screening for suicide risk",["booking photos","parole review","sentencing"],"Screening identifies risk early.")
H("747.d.13.A",4,"Screening for suicide risk at intake typically includes:","asking about past attempts, current thoughts and recent stressors",["only asking height","only taking photos","ignoring answers"],"Intake questions reveal risk.")
H("747.d.13.B",3,"A facility places an at-risk inmate on observation and alerts mental health staff. This is a procedure for:","preventing suicide among prisoners",["ignoring signs","punishing","isolating forever"],"Observation and referral save lives.")
H("747.d.13.B",4,"If an officer finds an inmate attempting to self-harm, the officer should:","call for help and begin emergency aid",["leave","wait","ignore"],"Immediate response is required.")
H("747.d.13.C",3,"A newly booked person arrives shaking and confused after heavy drinking. Staff must classify and deal with:","intoxicated persons safely and promptly",["only paperwork","only clothing","only meals"],"Intoxication can be a medical emergency.")
H("747.d.13.C",4,"Why must officers monitor intoxicated detainees closely?","Intoxication or withdrawal can cause medical emergencies",["It's fun","It is unneeded","It speeds booking"],"Withdrawal can be dangerous.")
H("747.d.14.A",3,"At booking, an officer records personal data, takes fingerprints and inventories belongings. These are:","general booking procedures",["court procedures","parole procedures","hiring procedures"],"Booking creates the record.")
H("747.d.14.A",4,"Which step is part of booking?","fingerprinting and photographing the person",["issuing a diploma","approving a loan","granting parole"],"Fingerprints and photos are standard.")
H("747.d.14.B",3,"After booking, medical screening and classification occur before assignment to a cell. This is part of the:","prisoner admission process",["release process","trial","appeal"],"Admission includes screening and classification.")
H("747.d.14.B",4,"The admission process for a new prisoner typically includes:","medical screening, property inventory and classification",["graduation","a vote","a trial"],"Admission steps prepare placement.")
H("747.d.14.C",3,"An officer verifies identity, returns property and records the time when someone leaves custody. This is the:","process for releasing prisoners",["booking process","trial process","parole denial"],"Release has set steps.")
H("747.d.14.C",4,"Before releasing a prisoner, staff must confirm:","the person's identity and the legal authority for release",["their favorite color","their shoe size","their lunch choice"],"Identity and authority prevent errors.")
H("747.d.15.A",3,"An officer notices an inmate muttering and refusing to eat for days and reports it. This is identifying:","symptoms of a mental impairment",["normal behavior always","nothing","a hobby"],"Behavior changes can signal illness.")
H("747.d.15.A",4,"Which observed change might signal a mental health issue in an inmate?","sudden withdrawal, confusion or extreme mood swings",["a regular meal","routine exercise","reading"],"Sudden changes warrant referral.")
H("747.d.15.B",3,"At intake, staff ask an inmate whether they have ever been treated for mental illness or taken psychiatric medication. These are:","screening questions for mental illness",["menu choices","visiting rules","clothing sizes"],"Screening questions identify needs.")
H("747.d.15.B",4,"A screening question for mental illness at booking would be:","Have you ever received mental health treatment or medication?",["What is your favorite food?","What sport do you play?","What is your car color?"],"History informs care.")
H("747.d.15.C",3,"Staff keep an inmate's medical file secure and share it only with authorized people. This is:","maintaining health records with attention to privacy",["sharing publicly","deleting files","ignoring privacy"],"Health records are confidential.")
H("747.d.15.C",4,"Why are inmate health records kept confidential?","Privacy laws and policy protect sensitive medical information",["Records are worthless","Anyone may read them","They are entertainment"],"Confidentiality is required.")
H("747.d.15.D",3,"A court rules that jails must provide necessary medical care. This is a:","legal aspect of health care in a detention facility",["menu rule","staff dress code","visiting-hours rule"],"Law requires adequate care.")
H("747.d.15.D",4,"Which statement is true about health care in a detention facility?","Facilities have a legal duty to provide necessary medical care",["Care is optional","Only staff get care","No care is ever allowed"],"Deliberate indifference violates rights.")
H("747.d.16",3,"A jail provides visitation, mail, library access, religious services and phone calls. These are:","various prisoner services",["staff benefits","court services","school services"],"Prisoners receive regulated services.")
H("747.d.16",4,"Providing prisoner services such as mail and visitation requires facilities to:","follow rules that balance access and security",["ignore security","eliminate all services","allow unlimited contraband"],"Services are provided within security limits.")
H("747.d.17.A",3,"Officers count every inmate at set times to be sure no one is missing. This identifies the importance of:","inmate counts",["menu planning","staff parties","court dates"],"Counts verify everyone is accounted for.")
H("747.d.17.A",4,"If an inmate count does not match the expected total, officers should:","recount and notify a supervisor",["ignore it","guess","skip the count"],"Discrepancies must be resolved.")
H("747.d.17.B",3,"An officer lists each item a new inmate brings in, seals it in a bag and has the inmate sign. This is:","inventorying a prisoner's property",["searching a cell","releasing the person","writing a report"],"Property must be documented.")
H("747.d.17.B",4,"Why is an inventory of prisoner property signed by the inmate?","It documents what was received and prevents disputes",["It's fun","It's not needed","It hides items"],"Signatures create a record.")
H("747.d.17.C",3,"Searching a prisoner requires officers to follow rules about the person's gender and privacy. This is the process of:","searching male and female prisoners properly",["ignoring privacy","skipping the search","searching at random"],"Search rules protect dignity and safety.")
H("747.d.17.C",4,"A pat-down search of a prisoner should be performed by an officer who:","follows policy and, when required, is of the same gender",["picks anyone","is untrained","avoids policy"],"Policy dictates who searches.")
H("747.d.17.D",3,"Officers check beds, vents and shared tables for hidden weapons or drugs. This is the process for:","searching cells and common areas",["booking","parole","trial"],"Cell searches detect contraband.")
H("747.d.17.D",4,"The main purpose of searching cells and common areas is to find:","contraband and security threats",["art projects","menu items","furniture brands"],"Searches protect safety.")
H("747.d.17.E",3,"Broken locks, propped doors and unsecured keys are examples of:","issues involving facility security",["housekeeping goals","kitchen duties","fashion choices"],"They create security risks.")
H("747.d.17.E",4,"Which practice helps maintain facility security?","Controlling keys and checking locks regularly",["Leaving doors propped","Sharing keys freely","Ignoring broken locks"],"Key control is basic.")
H("747.d.18.A",3,"Staff follow a plan to regain control when many inmates refuse orders at once. This is a procedure for:","responding to a riot or disturbance",["a parole hearing","a booking","a food delivery"],"Riots require coordinated response.")
H("747.d.18.A",4,"The first priority for staff responding to a disturbance is to:","protect life and secure the area",["leave the post","ignore it","join in"],"Safety and control first.")
H("747.d.18.B",3,"Officers practice what to do for an assault, a fire or a medical emergency inside a housing unit. These are:","procedures for responding to emergency events",["recipes","school plans","parking plans"],"Training prepares for varied emergencies.")
H("747.d.18.B",4,"When a fire alarm sounds in a unit, staff should:","follow the evacuation plan and account for inmates",["ignore it","hide","wait"],"Plans protect people.")
H("747.d.18.C",3,"An officer deals with an inmate who repeatedly shouts and disrupts a group. This is a problem with:","disruptive inmates and groups",["court procedure","parole","booking"],"Disruptive behavior must be managed.")
H("747.d.18.C",4,"A good first response to a disruptive inmate is to:","give a clear verbal direction and use de-escalation",["use force immediately","ignore","argue"],"Start with the least force.")
H("747.d.18.D",3,"After a missing inmate is discovered, staff lock down the facility, notify law enforcement and search. This is the procedure for:","escape attempts and escapes",["intake","parole","release"],"Escapes trigger specific steps.")
H("747.d.18.D",4,"When an escape is suspected, staff should immediately:","secure the facility and notify supervisors and law enforcement",["wait a day","ignore it","tell the media first"],"Rapid notification is key.")
H("747.d.19.A",3,"After an incident, an officer writes facts, times and actions in order and checks for accuracy. This shows the process of:","writing reports",["ignoring events","guessing","deleting evidence"],"Accurate reports matter.")
H("747.d.19.A",4,"A good incident report is:","factual, objective and complete",["emotional","vague","biased"],"Reports must be reliable.")
H("747.d.19.B",3,"An officer who must testify in court wears a clean uniform, speaks respectfully and stays calm. This is:","appropriate courtroom attire and demeanor",["casual dress","arguing","ignoring the judge"],"Professional appearance matters.")
H("747.d.19.B",4,"Which demeanor is appropriate for a witness in court?","calm, respectful and truthful",["angry","joking","evasive"],"Credibility depends on demeanor.")
H("747.d.19.C",3,"Before testifying, an officer reviews notes and reports and meets with the prosecutor. This is:","preparing for courtroom testimony",["avoiding court","skipping prep","guessing"],"Preparation ensures accurate testimony.")
H("747.d.19.C",4,"To prepare for testimony, an officer should:","review reports and be ready to answer truthfully",["memorize a script of lies","skip review","avoid the prosecutor"],"Truth and preparation matter.")
H("747.d.20.A",3,"In a training simulation, an officer moves from verbal commands to physical control only as the threat increases. This demonstrates the:","use of the force continuum",["use of random force","use of no force","use of ranks"],"The continuum escalates with the threat.")
H("747.d.20.A",4,"On the force continuum, the lowest level of response is usually:","officer presence and verbal commands",["deadly force","chemical agents","restraints only"],"Start with the least force.")
H("747.d.20.B",3,"State and federal laws limit how much force officers may use. These are:","guidelines and restrictions on use of force",["suggestions only","optional","rumors"],"Law restricts force.")
H("747.d.20.B",4,"Which statement describes legal limits on force by corrections officers?","Force must be reasonable and no more than necessary",["Force is unlimited","Force is for punishment","Force is optional"],"Reasonable force only.")
H("747.d.21",3,"A homeland security trainee practices breaking free from a hold and calling for help. This is analyzing:","procedures and protocols for self-defense",["avoiding training","ignoring risk","hiding"],"Self-defense procedures protect officers.")
H("747.d.21",4,"Self-defense protocols in homeland security emphasize:","protecting oneself and others using only necessary and lawful force",["unlimited force","attacking first","avoiding rules"],"Self-defense must be lawful.")

